(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const icons = {
    bell: '<path d="M6 10a6 6 0 0 1 12 0c0 7 3 7 3 8H3c0-1 3-1 3-8Z"/><path d="M9 21h6M12 2v2"/>',
    speech: '<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z"/><path d="M7 10h10M7 14h6"/>',
    bicycle: '<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-10 6 10H5l8-7h4M8 7h4M16 4h3l2 5"/>',
    horn: '<path d="m4 9 10-5v16L4 15H2V9h2Z"/><path d="M18 8c2 2 2 6 0 8M21 5c4 4 4 10 0 14"/>',
    touch: '<path d="M9 12V5a2 2 0 0 1 4 0v8-3a2 2 0 0 1 4 0v3-1a2 2 0 0 1 4 0v4c0 5-3 7-7 7h-2c-3 0-4-2-6-5l-3-4a2 2 0 0 1 3-3l3 3"/><path d="M3 4 1 2M19 4l2-2"/>',
    wave: '<path d="M3 9v6M7 6v12M12 2v20M17 6v12M21 9v6"/>',
    lock: '<rect x="5" y="10" width="14" height="12" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 15v3"/>',
    chip: '<rect x="5" y="5" width="14" height="14" rx="3"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M8 1v4M16 1v4M8 19v4M16 19v4M1 8h4M1 16h4M19 8h4M19 16h4"/>',
    direction: '<circle cx="12" cy="12" r="10"/><path d="m16 6-2 8-8 4 4-8 6-4Z"/>',
    pause: '<path d="M8 5v14M16 5v14"/>',
    check: '<path d="m5 12 4 4L20 5"/>',
    watch: '<circle cx="12" cy="12" r="7"/><path d="m8 6 1-5h6l1 5M8 18l1 5h6l1-5M19 10h2v4h-2"/>',
    mic: '<rect x="8" y="2" width="8" height="13" rx="4"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v4M8 23h8"/>'
  };
  const ico = (name) => '<svg viewBox="0 0 24 24" aria-hidden="true">' + (icons[name] || icons.wave) + '</svg>';
  const events = {
    bell: {title:'Doorbell',subtitle:'Someone may be at the door',color:'#b7e4c6',pattern:'pair',icon:'bell'},
    speech: {title:'Speech nearby',subtitle:'A moment to look up',color:'#a8d4e9',pattern:'long',icon:'speech'},
    bicycle: {title:'Bicycle bell',subtitle:'Take a look around',color:'#f0c494',pattern:'short',icon:'bicycle'},
    horn: {title:'Vehicle horn',subtitle:'Take a look around',color:'#f0c494',pattern:'short',icon:'horn'},
    ready: {title:'SoundBridge',subtitle:'Your world, in touch',color:'#b7e4c6',pattern:'pair',icon:'wave'},
    paused: {title:'A little quiet',subtitle:'Listening is paused',color:'#a5b3aa',pattern:'long',icon:'pause'}
  };
  const pattern = name => '<div class="watch-pattern '+(name==='pair'?'pair':name==='long'?'long':'')+'">'+'<i></i>'.repeat(name==='pair'?4:name==='long'?1:3)+'</div>';
  const ticks=Array.from({length:36},(_,i)=>'<line class="tick" x1="180" y1="20" x2="180" y2="'+(i%3?23:27)+'" transform="rotate('+i*10+' 180 180)"/>').join('');
  const watch=(type='bell',o={})=>{
    const e=events[type];
    return '<div class="watch '+(o.cls||'')+(o.direction===false?' no-direction':'')+'" data-event="'+type+'" style="--bearing:'+(o.angle??-45)+'deg;--alert:'+e.color+'"><div class="watch-band"></div><div class="watch-case"><div class="watch-bezel"><div class="watch-screen"><svg class="radar" viewBox="0 0 360 360" aria-hidden="true"><circle cx="180" cy="180" r="153" fill="none" stroke="#c7d6ca" stroke-width=".5" opacity=".13"/>'+ticks+'<g class="bearing-group"><path class="sector" d="M180 180 L105 50.1 A150 150 0 0 1 255 50.1 Z"/><path class="sector-line" d="M180 180 105 50.1M180 180 255 50.1"/><path class="direction-arc" d="M105 50.1 A150 150 0 0 1 255 50.1"/><circle class="beacon" cx="180" cy="30" r="4"/></g></svg><div class="watch-time">10:09</div><div class="watch-face-content"><div class="watch-face-icon">'+ico(e.icon)+'</div><div class="watch-title">'+e.title+'</div><div class="watch-subtitle">'+(o.subtitle||e.subtitle)+'</div>'+pattern(e.pattern)+'</div>'+(o.setup||'')+'</div></div></div></div>';
  };
  const photo=(n,caption='',cls='')=>'<div class="photo '+(caption?'captioned ':'')+cls+'" data-photo="'+n+'"><img src="assets/everyday-moments.png" alt="'+['Illustrative scene of a woman preparing food at home, wearing a watch.','Illustrative scene of colleagues sharing a conversation in a studio.','Illustrative scene of a person noticing a cyclist on a park path.'][n]+'" draggable="false">'+(caption?'<div class="photo-caption">'+caption+'</div>':'')+'</div>';
  const eyebrow=t=>'<p class="eyebrow">'+t+'</p>';
  const copy=(t,lead,label='')=>'<div class="copy" data-reveal>'+(label?eyebrow(label):'')+'<h2>'+t+'</h2>'+(lead?'<p class="lead">'+lead+'</p>':'')+'</div>';
  const slides=[
    {title:'A little closer to your world.',chapter:'The idea',cls:'hero',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('FEEL THE MOMENT. SEE WHERE TO LOOK.')+'<h1>A little closer<br>to your world.</h1><p class="lead">A standalone sound-aware watch.<br>For the moments that bring us together.</p><div class="button-row"><button class="button" data-go="4">Meet SoundBridge <span>↗</span></button><span class="micro-label">BEYOND THE SCREEN</span></div></div><div class="hero-visual" data-reveal><div class="watch-tilt">'+watch('bell')+'</div><span class="hero-label">A wearable concept. An everyday connection.</span></div></div>'},
    {title:'Some moments begin with a sound.',chapter:'Everyday moments',cls:'white',html:'<div class="inner split reverse"><div class="photo-stage" data-reveal>'+photo(0,'','single-photo')+'</div>'+copy('Some moments<br>begin with<br>a sound.','A doorbell. A conversation.<br>A bicycle passing by.','THE SMALL THINGS')+'</div>'},
    {title:'Stay in the moment. Stay connected.',chapter:'Everyday moments',cls:'',html:'<div class="inner center-top"><div class="center" data-reveal>'+eyebrow('EVERYDAY LIFE, ON YOUR TERMS')+'<h2 class="medium">Stay in the moment.<br>Stay connected.</h2></div><div class="photos-three" data-reveal>'+photo(0,'A welcome at home.')+photo(1,'A moment shared.')+photo(2,'Your own pace.')+'</div></div>'},
    {title:'A sound. A feeling. A little context.',chapter:'The experience',cls:'sage',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('THE SOUNDBRIDGE EXPERIENCE')+'<h2>A sound.<br>A feeling.<br>A little context.</h2><p class="lead">Recognize a sound. Feel a distinct vibration.<br>Glance at what happened and where to look.</p><div class="segmented" id="event-tabs" aria-label="Preview a sound event"><button class="selected" data-preview="bell" aria-pressed="true">Doorbell</button><button data-preview="speech" aria-pressed="false">Speech</button><button data-preview="bicycle" aria-pressed="false">Bicycle bell</button></div><p class="fine-print">Interactive alert preview</p></div><div class="hero-visual" data-reveal>'+watch('bell',{cls:'experience-watch'})+'</div></div>'},
    {title:'Independence. Awareness. Choice.',chapter:'Why it matters',cls:'dark',html:'<div class="inner"><p class="eyebrow" data-reveal>MORE FREEDOM. LESS TO THINK ABOUT.</p><div class="quiet-word" data-reveal><span class="lit">Independence.</span><br><span>Awareness.</span><br><span>Choice.</span></div><div class="value-line" data-reveal>'+ico('watch')+'<p>A useful cue. A little more confidence.<br>The next move stays yours.</p></div></div>'},
    {title:'One watch. A complete experience.',chapter:'Independent by design',cls:'white',html:'<div class="inner split">'+copy('One watch.<br>A complete<br>experience.','Sense, recognize and respond.<br>The core experience lives on your wrist.','INDEPENDENT BY DESIGN')+'<div class="hero-visual" data-reveal><div class="orbit"></div>'+watch('ready',{direction:false})+'</div><div class="flow-strip" style="position:absolute;left:0;bottom:-10px" data-reveal><span>On-watch sensing</span><i>→</i><span>On-watch AI</span><i>→</i><span>Wrist alerts</span></div></div>'},
    {title:'Ready in a few simple taps.',chapter:'Make it yours',cls:'',html:'<div class="inner setup-grid"><div class="copy" data-reveal>'+eyebrow('SET UP ON THE WATCH')+'<h2>Ready in a few<br>simple taps.</h2><div class="step-list" id="setup-steps"><button class="step-item selected" data-step="0" aria-pressed="true"><span class="step-number">1</span><span><h3>Turn on sound awareness.</h3><p>You decide when listening begins.</p></span></button><button class="step-item" data-step="1" aria-pressed="false"><span class="step-number">2</span><span><h3>Choose your sounds.</h3><p>Keep the cues that matter to you.</p></span></button><button class="step-item" data-step="2" aria-pressed="false"><span class="step-number">3</span><span><h3>Find your feel.</h3><p>Preview a vibration that feels right.</p></span></button></div></div><div class="setup-watch-stage" data-reveal>'+watch('ready',{cls:'setup-watch',direction:false,setup:'<div class="watch-face-setup" id="setup-screen"></div>'})+'<span class="watch-knob">Tap the watch to explore setup.</span></div></div>'},
    {title:'Choose what matters to you.',chapter:'Make it yours',cls:'white',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('YOUR SOUNDS')+'<h2>Choose what<br>matters to you.</h2><p class="lead">A few familiar sounds.<br>One personal selection.</p><div class="sound-controls" id="sound-controls">'+[['bell','Doorbell'],['speech','Speech'],['bicycle','Bicycle bell'],['horn','Vehicle horn']].map(([key,label])=>'<button class="sound-toggle selected" data-sound="'+key+'" aria-pressed="true">'+ico(key)+'<span>'+label+'</span><span class="check">✓</span></button>').join('')+'</div><p class="selection-note" id="selection-note">4 sound types selected</p></div><div class="hero-visual" data-reveal>'+watch('ready',{cls:'selection-watch',direction:false,subtitle:'4 sounds selected'})+'</div></div>'},
    {title:'A language you can feel.',chapter:'Distinct tactile alerts',cls:'sage',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('RECOGNIZABLE AT A TOUCH')+'<h2>A language<br>you can feel.</h2><p class="lead">Different moments. Different patterns.<br>Learn them at your own pace.</p><div class="haptic-options" id="haptic-options"><button class="haptic-option selected" data-haptic="bell" aria-pressed="true"><span>Doorbell</span><span class="pulse-glyph pairs"><i></i><i></i><i></i><i></i></span><span class="play">▶</span></button><button class="haptic-option" data-haptic="speech" aria-pressed="false"><span>Speech</span><span class="pulse-glyph long"><i></i></span><span class="play">▶</span></button><button class="haptic-option" data-haptic="bicycle" aria-pressed="false"><span>Traffic cues</span><span class="pulse-glyph"><i></i><i></i><i></i></span><span class="play">▶</span></button></div><p class="haptic-status" id="haptic-status">Select a pattern to preview its rhythm.</p></div><div class="hero-visual" data-reveal>'+watch('bell',{cls:'haptic-watch',direction:false})+'</div></div>'},
    {title:'A sense of where. At a glance.',chapter:'Directional awareness',cls:'',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('A LITTLE SPATIAL CONTEXT')+'<h2>A sense of where.<br>At a glance.</h2><p class="lead">A soft sector marks an approximate<br>sound direction relative to the watch.</p><div class="direction-controls"><div class="range-header"><label for="bearing">Move the sound source</label><span id="bearing-value">315°</span></div><input class="range-input" id="bearing" type="range" min="-180" max="180" value="-45" step="1"><div class="range-ends"><span>← Rotate around the watch →</span><span>Illustrative range</span></div></div><p class="fine-print">Directional sensing assumes compatible multi-microphone hardware. The sector is a concept visualization, not a measured accuracy claim.</p></div><div class="direction-stage" data-reveal><div class="angle-orbit"><div class="sound-source" id="sound-source"></div></div>'+watch('bicycle',{cls:'direction-watch',angle:-45,subtitle:'Approximate direction'})+'<span class="direction-caption">The sector follows the watch’s frame of reference.</span></div></div>'},
    {title:'A welcome you can respond to.',chapter:'At home',cls:'warm editorial-slide',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('AT HOME')+'<h2>A welcome<br>you can<br>respond to.</h2><p class="lead">Stay with what you’re doing.<br>A gentle cue lets you know someone<br>may be at the door.</p><div class="button-row"><button class="button" data-scene-alert="bell">Preview the doorbell <span>↗</span></button></div><p class="fine-print">Your home. Your response. Your own time.</p></div><div class="photo-stage" data-reveal>'+photo(0,'','single-photo')+watch('bell',{angle:-55,cls:'scene-watch'})+'</div></div>'},
    {title:'Be part of the conversation.',chapter:'In conversation',cls:'white editorial-slide',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('IN CONVERSATION')+'<h2>Be part of<br>the conversation.</h2><p class="lead">A gentle cue when speech is nearby.<br>You choose when to use it.</p><div class="toggle-row"><div><h3>Conversation mode</h3><p id="conversation-state">Ready when you are.</p></div><button class="switch" id="conversation-toggle" role="switch" aria-checked="false" aria-label="Conversation mode"></button></div><p class="fine-print">Detecting speech does not identify who is being addressed.</p></div><div class="photo-stage" data-reveal>'+photo(1,'','single-photo')+watch('ready',{cls:'conversation-watch',direction:false})+'</div></div>'},
    {title:'Your pace. A little more context.',chapter:'Out and about',cls:'sage editorial-slide',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('OUT AND ABOUT')+'<h2>Your pace.<br>A little more<br>context.</h2><p class="lead">A bicycle bell becomes a wrist alert.<br>Pause. Look around.<br>Continue your day.</p><div class="button-row"><button class="button" data-scene-alert="bicycle">Preview a bicycle bell <span>↗</span></button></div><p class="fine-print">An awareness aid. Not a navigation or collision-avoidance system.</p></div><div class="photo-stage" data-reveal>'+photo(2,'','single-photo')+watch('bicycle',{angle:55,cls:'scene-watch'})+'</div></div>'},
    {title:'A different rhythm for every day.',chapter:'Fits your routine',cls:'',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('THE RIGHT CUES, AT THE RIGHT TIME')+'<h2>A different rhythm<br>for every part<br>of your day.</h2><div class="segmented" id="mode-tabs" aria-label="Choose an awareness mode"><button class="selected" data-mode="home" aria-pressed="true">Home</button><button data-mode="conversation" aria-pressed="false">Conversation</button><button data-mode="outdoors" aria-pressed="false">Outdoors</button></div><div class="mode-chips" id="mode-chips"><span>Doorbell</span></div><p class="mode-situation" id="mode-situation">Focus on familiar cues at home.<br>Ordinary speech stays in the background.</p></div><div class="mode-stage" data-reveal><div class="mode-background"></div>'+watch('bell',{cls:'mode-watch'})+'</div></div>'},
    {title:'You decide when to tune in.',chapter:'Always your choice',cls:'white',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('CONTROL STAYS WITH YOU')+'<h2>You decide<br>when to tune in.</h2><p class="lead">Turn awareness on for the moments<br>you want. Pause whenever you prefer.</p><div class="toggle-row"><div><h3>Sound awareness</h3><p id="listening-state">On. Ready for your selected sounds.</p></div><button class="switch on" id="listening-toggle" role="switch" aria-checked="true" aria-label="Sound awareness"></button></div></div><div class="hero-visual" id="listening-visual" data-reveal><div class="breathe-rings"><i></i><i></i><i></i></div>'+watch('ready',{cls:'listening-watch',direction:false})+'</div></div>'},
    {title:'Your wrist. Your way.',chapter:'Personal by design',cls:'sage',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('SMALL ADJUSTMENTS. A PERSONAL FIT.')+'<h2>Your wrist.<br>Your way.</h2><p class="lead">Clearer text. A different feel.<br>A watch that fits your preferences.</p><div class="personalize-controls"><div class="control-group"><label for="text-size"><span>Text size</span><span id="text-size-value">Standard</span></label><input class="range-input" id="text-size" type="range" min="80" max="125" value="100" step="5"></div><div class="control-group"><label>Vibration strength</label><div class="segmented" id="strength-tabs"><button data-strength="Gentle" aria-pressed="false">Gentle</button><button class="selected" data-strength="Balanced" aria-pressed="true">Balanced</button><button data-strength="Strong" aria-pressed="false">Strong</button></div></div></div></div><div class="hero-visual" data-reveal>'+watch('bell',{cls:'personal-watch',direction:false})+'</div></div>'},
    {title:'Personal by nature.',chapter:'Privacy on your wrist',cls:'white',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('A LOCAL-FIRST CONCEPT')+'<h2>Personal<br>by nature.</h2><p class="lead">Core recognition runs on the watch.<br>Raw recordings aren’t saved by default.<br>Your moments stay yours.</p><div class="feature-quiet-row"><span>'+ico('chip')+'On-watch processing</span><span>'+ico('lock')+'User-controlled history</span></div><p class="fine-print">Proposed privacy defaults. Final hardware and software behavior require validation.</p></div><div class="hero-visual" data-reveal><div class="privacy-orb"><div class="privacy-halo"></div>'+watch('ready',{direction:false})+'<span class="privacy-tag">'+ico('lock')+'Designed to stay on your wrist</span></div></div></div>'},
    {title:'Designed to listen. Built to respond.',chapter:'The concept inside',cls:'',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('THE CONCEPT INSIDE')+'<h2>Designed to listen.<br>Built to respond.</h2><p class="lead">A complete sensing loop,<br>imagined for a single wearable.</p><p class="fine-print">Proposed architecture. Next: hardware selection, acoustic validation, battery testing and real-world trials.</p></div><div class="architecture-visual" data-reveal><div class="architecture-part"><span>01</span>'+ico('mic')+'<div><h3>Sense the surroundings.</h3><p>Microphones capture environmental sounds.</p></div></div><div class="architecture-part"><span>02</span>'+ico('chip')+'<div><h3>Understand on the watch.</h3><p>Local sound AI and hardware-dependent direction sensing.</p></div></div><div class="architecture-part"><span>03</span>'+ico('touch')+'<div><h3>Make the moment perceptible.</h3><p>A distinct vibration. A clear event. A direction sector.</p></div></div></div></div>'},
    {title:'Let the people who wear it lead.',chapter:'Built around real lives',cls:'white editorial-slide',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('THE NEXT CHAPTER')+'<h2>Let the people<br>who wear it<br>lead.</h2><p class="lead">Next comes co-design with deaf<br>and hard-of-hearing people.<br>Their routines. Their feedback. Their choices.</p><div class="co-design-words"><span>Listen</span><span>Try together</span><span>Refine</span></div></div><div class="photo-stage" data-reveal>'+photo(1,'','single-photo')+'<p class="photo-credit">Illustrative concept photography. No completed user study is implied.</p></div></div>'},
    {title:'Your world. A little more within reach.',chapter:'SoundBridge',cls:'closing sage',html:'<div class="inner split"><div class="copy" data-reveal>'+eyebrow('SOUNDBRIDGE')+'<h2>Your world.<br>A little more<br>within reach.</h2><p class="lead">Feel the moment.<br>See where to look.<br>Choose your next move.</p><div class="ending-links"><button class="button" data-go="7">Try the setup <span>↗</span></button><button class="text-link" data-go="4">Replay the experience</button></div><p class="ending-note">A standalone wearable concept · Beyond the Screen</p></div><div class="hero-visual" data-reveal><div class="watch-tilt">'+watch('ready',{direction:false})+'</div></div></div>'}
  ];
  const deck=$('#deck');
  deck.innerHTML=slides.map((s,i)=>'<section class="slide '+s.cls+'" id="slide-'+(i+1)+'" data-page="'+String(i+1).padStart(2,'0')+'" aria-label="Slide '+(i+1)+': '+s.title+'" aria-hidden="true" inert>'+s.html+'</section>').join('');
  const sections=$$('.slide');
  $('#progress-dots').innerHTML=slides.map((s,i)=>'<button data-go="'+(i+1)+'" aria-label="Slide '+(i+1)+': '+s.title+'" title="'+(i+1)+' · '+s.title+'"></button>').join('');
  $('#overview-grid').innerHTML=slides.map((s,i)=>'<button class="overview-slide '+(s.cls.includes('dark')?'dark':'')+'" data-go="'+(i+1)+'"><small>'+String(i+1).padStart(2,'0')+'</small><strong>'+s.title+'</strong></button>').join('');
  let current=-1,changing=false,pending=null;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
  const state={sounds:new Set(['bell','speech','bicycle','horn']),setup:0,mode:'home',listening:true,strength:'Balanced'};
  function announce(t){$('#announcement').textContent=t;}
  function updateChrome(){
    const s=slides[current];document.body.classList.toggle('is-dark',s.cls.includes('dark'));
    $('#chapter-label').textContent=s.chapter;$('#slide-number').innerHTML=String(current+1).padStart(2,'0')+' <span>/ 20</span>';
    $$('#progress-dots button').forEach((b,i)=>{b.classList.toggle('active',i===current);b.setAttribute('aria-current',i===current?'step':'false');});
    $$('.overview-slide').forEach((b,i)=>b.classList.toggle('selected',i===current));
    $('#previous').disabled=current===0;$('#next').disabled=current===slides.length-1;
    document.title='SoundBridge — '+s.title;history.replaceState(null,'','#'+(current+1));
    if(current!==0)$('#keyboard-hint').classList.add('hide');
    announce('Slide '+(current+1)+' of '+slides.length+'. '+s.title);
  }
  async function goTo(n,instant=false){
    const target=Math.max(0,Math.min(slides.length-1,Number(n)-1));if(target===current)return;
    if(changing){pending=target+1;return;}changing=true;
    const previous=current,old=sections[previous],next=sections[target],direction=target>previous?1:-1;current=target;
    if(old){old.classList.remove('active');old.classList.add('leaving');old.inert=true;old.setAttribute('aria-hidden','true');}
    next.classList.add('active');next.inert=false;next.setAttribute('aria-hidden','false');next.scrollTop=0;updateChrome();
    const duration=instant||reduced.matches?0:760,easing='cubic-bezier(.22,1,.36,1)';
    if(duration){
      const animations=[];
      if(old)animations.push(old.animate([{opacity:1,transform:'translate3d(0,0,0)'},{opacity:0,transform:'translate3d('+(-direction*40)+'px,0,0)'}],{duration:duration*.8,easing,fill:'both'}).finished.catch(()=>{}));
      animations.push(next.animate([{opacity:0,transform:'translate3d('+(direction*45)+'px,0,0)'},{opacity:1,transform:'translate3d(0,0,0)'}],{duration,easing}).finished.catch(()=>{}));
      $$('[data-reveal]',next).forEach((el,i)=>el.animate([{opacity:0,transform:'translate3d(0,22px,0)'},{opacity:1,transform:'translate3d(0,0,0)'}],{duration:850,delay:80+i*75,easing}));
      await Promise.all(animations);
    }
    if(old){old.classList.remove('leaving');old.getAnimations().forEach(a=>a.cancel());}
    changing=false;if(pending!==null){const t=pending;pending=null;if(t!==current+1)goTo(t);}
  }
  function face(w,type,subtitle){
    if(!w)return;const e=events[type];w.dataset.event=type;w.style.setProperty('--alert',e.color);
    $('.watch-face-icon',w).innerHTML=ico(e.icon);$('.watch-title',w).textContent=e.title;$('.watch-subtitle',w).textContent=subtitle||e.subtitle;$('.watch-pattern',w).outerHTML=pattern(e.pattern);
  }
  function pulse(w){if(!w)return;w.classList.remove('vibrating');void w.offsetWidth;w.classList.add('vibrating');setTimeout(()=>w.classList.remove('vibrating'),1300);}
  function selectedButtons(parent,button){$$('button',parent).forEach(b=>{const yes=b===button;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});}
  function setupStep(n){
    state.setup=n;$$('.step-item').forEach((b,i)=>{b.classList.toggle('selected',i===n);b.setAttribute('aria-pressed',String(i===n));});
    const panels=[
      '<span class="mini-brand">SOUNDBRIDGE</span><h3>A little closer.</h3><p>Turn on sound awareness<br>when you’re ready.</p><button id="setup-next">Get started</button>',
      '<span class="mini-brand">YOUR SOUNDS</span><h3>Keep what matters.</h3><div class="setup-sound-list"><span>Doorbell <b>✓</b></span><span>Speech <b>✓</b></span><span>Bicycle bell <b>✓</b></span></div><button id="setup-next">Continue</button>',
      '<span class="mini-brand">FIND YOUR FEEL</span><h3>Feel connected.</h3><p>Two gentle taps.<br>A familiar cue.</p><button id="setup-test">Preview vibration</button>'
    ];
    $('#setup-screen').innerHTML=panels[n];$('.watch-face-content',$('.setup-watch')).style.visibility='hidden';
    if($('#setup-next'))$('#setup-next').onclick=()=>setupStep((state.setup+1)%3);
    if($('#setup-test'))$('#setup-test').onclick=()=>{pulse($('.setup-watch'));$('#setup-test').textContent='Try again';announce('Vibration pattern preview.');};
  }
  setupStep(0);
  $$('.step-item').forEach(b=>b.addEventListener('click',()=>setupStep(Number(b.dataset.step))));
  $$('#event-tabs button').forEach(b=>b.addEventListener('click',()=>{selectedButtons($('#event-tabs'),b);const w=$('.experience-watch');face(w,b.dataset.preview);w.style.setProperty('--bearing',(b.dataset.preview==='speech'?25:b.dataset.preview==='bell'?-45:65)+'deg');pulse(w);}));
  $$('.sound-toggle').forEach(b=>b.addEventListener('click',()=>{
    const key=b.dataset.sound;if(state.sounds.has(key))state.sounds.delete(key);else state.sounds.add(key);
    const selected=state.sounds.has(key);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));
    const n=state.sounds.size;$('#selection-note').textContent=n?n+' sound '+(n===1?'type':'types')+' selected':'No sounds selected. You can choose any time.';
    face($('.selection-watch'),'ready',n?n+' '+(n===1?'sound':'sounds')+' selected':'Choose your sounds');
  }));
  $$('.haptic-option').forEach(b=>b.addEventListener('click',()=>{selectedButtons($('#haptic-options'),b);const key=b.dataset.haptic;face($('.haptic-watch'),key);pulse($('.haptic-watch'));$('#haptic-status').textContent={bell:'Previewing two taps, a pause, then two taps.',speech:'Previewing one longer, gentle cue.',bicycle:'Previewing three short, distinct taps.'}[key];announce($('#haptic-status').textContent);}));
  $('#bearing').addEventListener('input',e=>{const v=Number(e.target.value);$('.direction-watch').style.setProperty('--bearing',v+'deg');$('#sound-source').style.setProperty('--source-angle',v+'deg');$('#bearing-value').textContent=String((v+360)%360)+'°';});
  $$('[data-scene-alert]').forEach(b=>b.addEventListener('click',()=>{const w=$('.scene-watch',b.closest('.slide'));face(w,b.dataset.sceneAlert);pulse(w);b.textContent='Preview again ↗';}));
  $('#conversation-toggle').addEventListener('click',()=>{const b=$('#conversation-toggle'),on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(on));b.classList.toggle('on',on);$('#conversation-state').textContent=on?'On. A gentle cue for nearby speech.':'Ready when you are.';face($('.conversation-watch'),on?'speech':'ready',on?undefined:'Conversation mode is off');if(on)pulse($('.conversation-watch'));});
  const modes={
    home:{type:'bell',chips:['Doorbell'],text:'Focus on familiar cues at home.<br>Ordinary speech stays in the background.',bg:'#e1e9e3',angle:-45},
    conversation:{type:'speech',chips:['Speech','Doorbell'],text:'Choose when to listen for nearby speech.<br>A cue to look up, without identifying who is being addressed.',bg:'#e0eaf0',angle:25},
    outdoors:{type:'bicycle',chips:['Bicycle bell','Vehicle horn'],text:'Keep traffic-related cues in view.<br>Always look around and judge the situation yourself.',bg:'#ece3d8',angle:65}
  };
  $$('#mode-tabs button').forEach(b=>b.addEventListener('click',()=>{state.mode=b.dataset.mode;selectedButtons($('#mode-tabs'),b);const m=modes[state.mode];face($('.mode-watch'),m.type);$('.mode-watch').style.setProperty('--bearing',m.angle+'deg');$('.mode-background').style.background=m.bg;$('#mode-chips').innerHTML=m.chips.map(c=>'<span>'+c+'</span>').join('');$('#mode-situation').innerHTML=m.text;pulse($('.mode-watch'));}));
  $('#listening-toggle').addEventListener('click',()=>{state.listening=!state.listening;const b=$('#listening-toggle');b.classList.toggle('on',state.listening);b.setAttribute('aria-checked',String(state.listening));$('#listening-state').textContent=state.listening?'On. Ready for your selected sounds.':'Paused. Resume whenever you choose.';face($('.listening-watch'),state.listening?'ready':'paused');$('.listening-watch').classList.toggle('paused',!state.listening);$('#listening-visual').classList.toggle('is-paused',!state.listening);});
  $('#text-size').addEventListener('input',e=>{const v=Number(e.target.value);$('.personal-watch .watch-title').style.fontSize='calc(var(--size) * '+(.092*v/100)+')';$('#text-size-value').textContent=v<100?'Smaller':v===100?'Standard':'Larger';});
  $$('#strength-tabs button').forEach(b=>b.addEventListener('click',()=>{state.strength=b.dataset.strength;selectedButtons($('#strength-tabs'),b);pulse($('.personal-watch'));$('.personal-watch .watch-subtitle').textContent=state.strength+' vibration';}));
  document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){if($('#overview').open)$('#overview').close();goTo(Number(go.dataset.go));}const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();});
  $('#previous').addEventListener('click',()=>goTo(current));$('#next').addEventListener('click',()=>goTo(current+2));
  const toggleDialog=id=>{const d=$('#'+id);if(d.open)d.close();else d.showModal();};
  $('#overview-toggle').addEventListener('click',()=>toggleDialog('overview'));$('#help-toggle').addEventListener('click',()=>toggleDialog('help'));
  $$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
  async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{announce('Fullscreen is not available here. Use your browser’s fullscreen control.');}}
  $('#fullscreen').addEventListener('click',fullscreen);document.addEventListener('fullscreenchange',()=>$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen'));
  $('#print').addEventListener('click',()=>{$('#help').close();window.print();});
  document.addEventListener('keydown',e=>{
    if(e.target.matches('input,textarea,select,[contenteditable=true]'))return;if($('#overview').open||$('#help').open)return;
    if(['ArrowRight','PageDown',' '].includes(e.key)){if(e.key===' '&&e.target.closest('button,a'))return;e.preventDefault();goTo(current+2);}
    else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();goTo(current);}
    else if(e.key==='Home'){e.preventDefault();goTo(1);}else if(e.key==='End'){e.preventDefault();goTo(slides.length);}
    else if(e.key.toLowerCase()==='f')fullscreen();else if(e.key.toLowerCase()==='o')toggleDialog('overview');else if(e.key==='?')toggleDialog('help');
  });
  let wheelTime=0;document.addEventListener('wheel',e=>{if(e.ctrlKey||e.target.closest('input,dialog'))return;const a=sections[current];if(a.scrollHeight>a.clientHeight+5)return;if(Math.abs(e.deltaY)<25)return;e.preventDefault();const now=performance.now();if(now-wheelTime<1050)return;wheelTime=now;goTo(current+(e.deltaY>0?2:0));},{passive:false});
  let touch=null;deck.addEventListener('touchstart',e=>{if(e.target.closest('button,input,a'))return;touch={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});deck.addEventListener('touchend',e=>{if(!touch)return;const dx=e.changedTouches[0].clientX-touch.x,dy=e.changedTouches[0].clientY-touch.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)goTo(current+(dx<0?2:0));touch=null;},{passive:true});
  window.addEventListener('hashchange',()=>{const n=Number(location.hash.slice(1));if(n)goTo(n);});
  window.SoundBridge={goTo,slideCount:slides.length,getState:()=>({slide:current+1,sounds:[...state.sounds],setup:state.setup,mode:state.mode,listening:state.listening,strength:state.strength}),slideTitles:slides.map(s=>s.title)};
  const initial=Number(location.hash.slice(1));goTo(Number.isFinite(initial)&&initial>0?initial:1,true);
})();
